/**
 * Billing term definitions + discount math, shared by ordering, renewal,
 * the deploy wizard, invoices and the domain flow. Discounts are the platform's
 * promo (longer commitment = cheaper); tune here (or later via admin Settings).
 */

export type VpsTerm = { months: number; label: string; short: string; discountPct: number };

/** The ANNUAL term is 12 months — the one term whose discount is admin-configurable. */
export const ANNUAL_TERM_MONTHS = 12;

/**
 * The annual (12-month) commitment discount SHIPPED as the default, and the fallback
 * for the `annual_discount_percent` admin setting (lib/annual-discount.ts).
 *
 * It MUST equal the 12-month `VPS_TERMS` discountPct below: a platform whose
 * `Setting` table has no `annual_discount_percent` row must price the annual term
 * EXACTLY as it did before the setting existed, so no existing annual server's
 * renewal price moves the moment this wiring lands. The setting only ever raises or
 * lowers it deliberately, from the admin Billing panel.
 */
export const DEFAULT_ANNUAL_DISCOUNT_PCT = 20;

export const VPS_TERMS: VpsTerm[] = [
  { months: 1, label: "Monthly", short: "1 mo", discountPct: 0 },
  // Annual is admin-configurable — this is only the SHIPPED default. Every charge
  // path resolves the live rate via `annualDiscountPct()` and passes it through
  // `vpsTermPriceCents`; this constant is what an un-wired caller (and a 2-arg call)
  // falls back to. Keep it === DEFAULT_ANNUAL_DISCOUNT_PCT.
  { months: 12, label: "Annual", short: "1 yr", discountPct: DEFAULT_ANNUAL_DISCOUNT_PCT },
  // Biennial/Triennial are FIXED platform rates (NOT admin-configurable), so for these
  // terms the order and every renewal read the SAME constant here → displayed ===
  // charged === renewed by construction, with no per-account freezing needed. Editing a
  // rate here only reprices NEW orders; any existing longer-term account simply renews
  // at the new (always-cheaper) rate — never an overcharge.
  { months: 24, label: "Biennial", short: "2 yr", discountPct: 30 },
  { months: 36, label: "Triennial", short: "3 yr", discountPct: 40 },
];

export function vpsTerm(months: number): VpsTerm {
  return VPS_TERMS.find((t) => t.months === months) ?? VPS_TERMS[0];
}

/**
 * The discount percent to apply to a term.
 *
 * For the ANNUAL (12-month) term this is admin-configurable: pass the
 * `annualDiscountPct` resolved from the `annual_discount_percent` setting
 * (lib/annual-discount.ts) and it WINS over the shipped default. Every other term
 * keeps its fixed `VPS_TERMS` rate. Omitting the override — or passing a
 * non-finite value — falls back to the shipped default, so a 2-arg
 * `vpsTermPriceCents` call and any caller that has not been wired up price annual at
 * `DEFAULT_ANNUAL_DISCOUNT_PCT`, i.e. exactly what the platform shipped before.
 * Clamped to 0..90 here as a second line of defence behind the setting reader.
 */
export function termDiscountPct(months: number, annualDiscountPct?: number): number {
  if (months === ANNUAL_TERM_MONTHS && annualDiscountPct != null && Number.isFinite(annualDiscountPct)) {
    return Math.min(90, Math.max(0, annualDiscountPct));
  }
  return vpsTerm(months).discountPct;
}

/**
 * Total charge (cents) for a plan over a term, discount applied.
 *
 * `annualDiscountPct` (optional) overrides the ANNUAL term's discount with the
 * admin-configured rate; see `termDiscountPct`. It is the ONE knob that makes
 * annual billing configurable while keeping this the single price formula —
 * displayed (deploy wizard), charged (lib/order.ts) and renewed (renewalCharge)
 * all call this with the SAME resolved rate, so they cannot disagree.
 */
export function vpsTermPriceCents(monthlyCents: number, months: number, annualDiscountPct?: number): number {
  const pct = termDiscountPct(months, annualDiscountPct);
  return Math.round(monthlyCents * months * (1 - pct / 100));
}

/**
 * Generic term price — the product-agnostic name for the ONE term formula above.
 * Shared Hosting, Business Email, Game servers and NxCloud all price a term as
 * `monthlyCents × months × (1 − annualDiscount)` exactly the way a VPS does, so
/**
 * VPS INTRO PRICING — a LOW first-term price that RENEWS at the regular price
 * (classic hosting promo: "$3.99/mo first term, renews at $6.49/mo").
 *
 * This is deliberately modelled as a FIRST-TERM-ONLY discount so it rides the
 * plumbing the platform already has, rather than adding a second renewal price:
 *
 *   - The ORDER (lib/order.ts) charges the intro-reduced first term and stamps the
 *     implied first-term rate on `Server.termPromoPercent` (the very column every
 *     later proration/refund already prices against — see lib/proration.ts).
 *   - RENEWAL (lib/renewal-charge.ts — the SINGLE renewal formula) reads
 *     `plan.priceCents` and knows NOTHING about `introPriceCents`, so a renewal is
 *     billed at the regular price by construction. No renewal code changes.
 *
 * Pure & deterministic (no `db`, no I/O), so it can be imported by the order core,
 * the marketing pricing cards and unit tests alike. The two READERS below cast to
 * reach `introPriceCents` / `introTermMonths` because the symlinked prod Prisma
 * client's types predate these columns until it is regenerated at deploy — the
 * same stale-client gap `frozenProductAnnualPct` (lib/product-billing.ts) and the
 * `Server` writes in lib/order.ts already work around. Identical at runtime once
 * the client is regenerated.
 */
import { termDiscountPct } from "./billing-terms";

/** A row that MAY carry the intro columns (present at runtime, absent from stale types). */
type PlanIntroFields = { introPriceCents?: number | null; introTermMonths?: number | null };

/**
 * The plan's intro MONTHLY price in cents, or null when it is unset, malformed, or
 * NOT genuinely below the regular price. Requiring `intro < regular` means a bad /
 * equal / higher value can never quietly RAISE the first-term charge — it just
 * disables the intro and the plan bills its regular price.
 *
 * `plan` is typed loose on the intro column because the symlinked prod Prisma client's
 * types predate it (regenerated at deploy); the value is present at runtime.
 */
export function planIntroMonthlyCents(plan: { priceCents: number }): number | null {
  const v = (plan as PlanIntroFields).introPriceCents;
  if (typeof v !== "number" || !Number.isFinite(v) || v < 0) return null;
  const cents = Math.round(v);
  if (cents >= plan.priceCents) return null;
  return cents;
}

/**
 * How many of the first term's months are billed at the intro rate. NULL / invalid
 * => the WHOLE first term (returned as null so callers apply it across every month).
 * Clamped to >= 1 so a stray 0 can never zero the intro window. `plan` is `unknown`
 * for the same stale-client reason as above.
 */
export function planIntroTermMonths(plan: unknown): number | null {
  const v = (plan as PlanIntroFields | null | undefined)?.introTermMonths;
  if (typeof v !== "number" || !Number.isFinite(v) || v < 1) return null;
  return Math.round(v);
}

/**
 * Cents knocked off the FIRST term because of the intro rate — 0 when there is no
 * intro. Expressed as a REDUCTION of the regular term total (not a second price)
 * so the regular term price stays the single source of truth and the renewal math
 * is untouched:
 *
 *   discount = (regularMonthly − introMonthly) × introMonths × (1 − termDiscount)
 *
 * `introMonths` is `min(introTermMonths ?? months, months)`, so a 1-month term is
 * fully intro-priced, and a "$3.99 first month" intro on a 12-month first order
 * discounts exactly one month and bills the other eleven at the regular rate.
 * The term discount is applied so the intro months are discounted consistently
 * with the rest of the term the customer chose.
 */
export function introFirstTermDiscountCents(
  regularMonthlyCents: number,
  introMonthlyCents: number | null,
  termMonths: number,
  introTermMonths: number | null,
  annualDiscountPct?: number,
): number {
  if (introMonthlyCents == null || introMonthlyCents >= regularMonthlyCents) return 0;
  const months = Math.max(1, Math.round(termMonths));
  const introMonths = introTermMonths != null ? Math.min(introTermMonths, months) : months;
  if (introMonths <= 0) return 0;
  const pct = termDiscountPct(months, annualDiscountPct);
  return Math.max(0, Math.round((regularMonthlyCents - introMonthlyCents) * introMonths * (1 - pct / 100)));
}

/**
 * The percent OFF the regular term total that the intro first term represents,
 * as a whole number 0..100 — the value stamped on `Server.termPromoPercent` so
 * proration and refunds price against the rate the term was actually sold at.
 * Integer because it round-trips through Stripe metadata as an integer promo
 * percent (lib/order.ts parseOrderPrice), exactly like the seasonal promos.
 */
export function introSoldPercent(regularTermCents: number, introDiscountCents: number): number {
  if (regularTermCents <= 0 || introDiscountCents <= 0) return 0;
  return Math.min(100, Math.max(0, Math.round((introDiscountCents / regularTermCents) * 100)));
}

// ---------- 4. Self-serve cancel / terminate (+ prorated refund) ----------

/**
 * Customer-initiated cancellation of a VPS / game server. Two modes:
 *
 *   • "period_end"  — stop auto-renew and keep the server running until `expiresAt`.
 *                     No money moves; the paid term is honoured to its end. Default
 *                     and always-safe choice.
 *   • "immediate"   — terminate NOW: enqueue the SAME audited DELETE job the manual
 *                     delete uses (worker destroys the VM), and — for a standard VPS
 *                     with unused paid time — credit the prorated refund to the WALLET
 *                     (never a Stripe refund; safer and reversible) in the same
 *                     transaction, with a ledger line and a credit-note invoice.
 *
 * Ownership-guarded and `assertNotImpersonating` (this both destroys a resource and
 * can move money — an admin must not do either on a customer's behalf). Respects the
 * one-in-flight-job invariant. The confirm dialog in the UI carries the data-retention
 * warning and the refund figure.
 */
export async function cancelService(
  serverId: string,
  mode: "immediate" | "period_end",
): Promise<{ error?: string; ok?: boolean; refundCents?: number; message?: string }> {
  // Moves money and destroys a resource — never while impersonating.
  await assertNotImpersonating();
  const { user, server } = await ownedServer(serverId);

  if (server.status === "DELETING") return { error: "This server is already being cancelled." };

  // ---- Cancel at period end: just stop auto-renew, keep the server to expiry. ----
  if (mode === "period_end") {
    if (server.isFree || !server.expiresAt) {
      return { error: "This server has no billing term to cancel — use immediate termination to remove it." };
    }
    if (!server.autoRenew) {
      return { ok: true, message: `Auto-renew is already off. This server stays active until ${server.expiresAt.toISOString().slice(0, 10)}, then stops.` };
    }
    await db.server.update({ where: { id: server.id }, data: { autoRenew: false } });
    await db.auditLog.create({
      data: { userId: user.id, action: "server.cancel_period_end", detail: serverId },
    });
    revalidatePath(`/dashboard/servers/${serverId}`);
    return {
      ok: true,
      message: `Auto-renew turned off. This server keeps running until ${server.expiresAt.toISOString().slice(0, 10)}, then stops automatically. You can turn auto-renew back on any time before then.`,
    };
  }

  // ---- Immediate termination (+ prorated wallet refund). ----
  if (await hasInflightJob(serverId)) {
    return { error: "Another operation is already in progress on this server. Wait for it to finish, then try again." };
  }

  const refundCents = terminationRefundCents({
    isFree: server.isFree,
    expiresAt: server.expiresAt,
    isGame: !!server.gamePlanId,
    planMonthlyCents: server.plan.priceCents,
    termMonths: server.termMonths,
    termPromoPercent: server.termPromoPercent,
    // Authoritative refund basis: the real plan cash collected for the term, net of
    // promo AND coupon. Null on legacy rows → the helper falls back to the (safe,
    // never-over-refunding) termPromoPercent formula.
    refundableTermCents: server.refundableTermCents,
    annualDiscountPct: frozenAnnualDiscountPct(server) ?? (await annualDiscountPct()),
  });

  // One INTERACTIVE transaction whose FIRST act is a compare-and-swap on status: flip
  // to DELETING only if it is not already DELETING. A double-click / retry that loses
257- * `annualDiscountPct` must be pre-resolved by the caller to
258- * `frozenAnnualDiscountPct(server) ?? liveRate`, mirroring the resize/downgrade paths.
