import { getSetting, getSettingBool } from "./settings";
import { stripeConfigured } from "./stripe";
import {
  LOCAL_METHODS, LOCAL_METHOD_IDS, localChargeCents, localMethodFlagKey, methodSupportedByEntity,
  parseLocalFxRates, type LocalMethod, type LocalMethodId,
} from "./local-payment-methods";

/**
 * Which Stripe local payment methods are REALLY offerable right now.
 *
 * A method is on only when ALL of these hold — each one is a way to avoid showing
 * (or letting through) a method that cannot take money:
 *   1. Stripe is configured;
 *   2. its per-method flag `pay_method_<id>` is true (default false);
 *   3. the Stripe account country (`stripe_account_country`, blank by default) is
 *      one Stripe supports the method for (lib/local-payment-methods.ts);
 *   4. it can be priced: USD methods always, SGD/INR methods only once an admin
 *      has entered an FX rate for that currency (`local_pay_fx_rates`).
 *
 * Server-only (reads settings). Never charges anything.
 */
export type EnabledLocalMethod = LocalMethod & { available: true };

export async function localPaymentConfig() {
  const [country, ratesJson, bufferRaw] = await Promise.all([
    getSetting("stripe_account_country"),
    getSetting("local_pay_fx_rates"),
    getSetting("local_pay_fx_buffer_pct"),
  ]);
  const buffer = Number(bufferRaw);
  return {
    entityCountry: country.trim().toUpperCase(),
    rates: parseLocalFxRates(ratesJson),
    bufferPct: Number.isFinite(buffer) ? buffer : 2,
  };
}

export async function enabledLocalMethods(): Promise<EnabledLocalMethod[]> {
  if (!stripeConfigured()) return [];
  const cfg = await localPaymentConfig();
  if (!cfg.entityCountry) return [];
  const out: EnabledLocalMethod[] = [];
  for (const id of LOCAL_METHOD_IDS) {
    if (!(await getSettingBool(localMethodFlagKey(id), false))) continue;
    if (!methodSupportedByEntity(id, cfg.entityCountry)) continue;
    // Pricing probe: 1 USD. null means no usable rate for this method's currency.
    if (localChargeCents({ usdCents: 100, method: id, rates: cfg.rates, bufferPct: cfg.bufferPct }) === null) continue;
    out.push({ ...LOCAL_METHODS[id], available: true });
  }
  return out;
}

export async function isLocalMethodEnabled(id: LocalMethodId): Promise<boolean> {
  return (await enabledLocalMethods()).some((m) => m.id === id);
}

