/** The per-month rate a game tier bills at. `GamePlan.priceCents` is the price
 *  for the plan's OWN term, so it is divided by that term — the same derivation
 *  lib/renewal-charge.ts uses for the game branch. Never re-derived elsewhere. */
export function gameMonthlyCents(plan: { priceCents: number; termMonths: number }): number {
  return Math.round(plan.priceCents / Math.max(1, plan.termMonths));
}

